function ValidateDoubleTextBox(n,t){if($.inArray(t.keyCode,[46,8,9,27,13,110])===-1&&(t.keyCode!==65||t.ctrlKey!==!0&&t.metaKey!==!0)&&(!(t.keyCode>=35)||!(t.keyCode<=40))){var i=n.value+t.key;if(i=i.replace(",","."),isNaN(i)){t.preventDefault();return}t.keyCode===190&&(t.preventDefault(),n.value=i)}}